// Generated by AI
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { SessionClient } from '../src/client/client.js';
import { describeBlocked, type ClientDiagnostic } from '../src/client/diagnostics.js';
import * as reducer from '../src/client/reducer.js';
import { identityFor } from '../../daemon/src/daemon/target.js';
import { FakeTransport, delta, snapshot } from './client-fixtures.js';

const clients: SessionClient[] = [];
const roots: string[] = [];
afterEach(async () => {
  vi.restoreAllMocks();
  for (const client of clients.splice(0)) client.close();
  await Promise.all(roots.splice(0).map(path => rm(path, { recursive: true, force: true })));
});
async function flushMicrotasks() { for (let index = 0; index < 30; index++) await Promise.resolve(); }
const cut = (session: string, revision = 0) => ({ ...snapshot(revision), session, root: session });
const invalidTool = (revision = 1) => ({ v: 1, session: 'session', rev: revision, change: {
  type: 'tool.updated', tool: { id: 'x'.repeat(129), name: 'read', message: 'message', state: 'completed', output: '', truncated: false },
} });

async function fixture() {
  const directory = await mkdtemp(join(tmpdir(), 'client-invalid-update-')); roots.push(directory);
  const fake = new FakeTransport();
  const diagnostics: ClientDiagnostic[] = [];
  const client = new SessionClient({ target: { kind: 'isolated', directory, namespaceId: 'client-test' },
    kind: 'tui', clientVersion: 'fixture', connector: fake.connector, reconnectAttempts: 0,
    diagnostics: event => diagnostics.push(event) });
  clients.push(client);
  const identity = identityFor(client.target, 'instance');
  fake.onSend = (request, connection) => {
    if (request.op === 'hello') fake.reply(request, { attachmentId: 'hello', principal: 'principal', daemonVersion: 'fixture',
      protocol: 1, identity, operations: ['attach', 'prompt'], interactionKinds: [] }, connection);
    else if (request.op === 'attach') fake.reply(request, { attachmentId: `binding-${request.session}`, snapshot: cut(request.session) }, connection);
    else fake.reply(request, { runId: 'run' }, connection);
  };
  await client.connect(); await client.attach('session'); await client.attach('other');
  return { client, fake, diagnostics };
}

describe('invalid session updates', () => {
  it.each([
    ['tool', invalidTool()],
    ['message', { v: 1, session: 'session', rev: 1, change: { type: 'message.completed', message: {} } }],
    ['stream', { ...delta('text'), stream: { ...delta('text').stream, offset: -1 } }],
  ] as const)('recovers an invalid %s update without interrupting another session', async (_kind, update) => {
    const { client, fake, diagnostics } = await fixture();
    const original = fake.onSend;
    fake.onSend = (request, connection) => { if (request.op !== 'attach') original(request, connection); };
    fake.frame(update);
    expect(client.status).toBe('ready');
    expect(client.getAttachment('session')?.state).toMatchObject({ status: 'recovering', recoveryAttempts: 1, recoveryCause: 'invalid_update', buffered: [] });
    fake.frame({ ...delta('uninterrupted'), session: 'other' });
    expect(await client.request('prompt', { text: 'continue' }, { session: 'other' })).toMatchObject({ outcome: 'accepted' });
    expect(client.getAttachment('other')?.state).toMatchObject({ status: 'live', snapshot: { activeStreams: [{ text: 'uninterrupted' }] } });
    const recovery = fake.requests.filter(request => request.op === 'attach').at(-1)!;
    fake.reply(recovery, { attachmentId: 'recovered', snapshot: cut('session', 1) });
    await flushMicrotasks();
    expect(client.getAttachment('session')?.state).toMatchObject({ status: 'live', recoveryAttempts: 1, snapshot: { revision: 1 } });
    expect(diagnostics).toContainEqual({ event: 'attachment.recovering', session: 'session', cause: 'invalid_update', attempts: 0, error: expect.any(String) });
    expect(diagnostics.some(event => event.event === 'connection.lost')).toBe(false);
    expect(fake.closed.size).toBe(0);
  });

  it('recovers a reducer exception through the same attachment path', async () => {
    const { client, fake, diagnostics } = await fixture();
    vi.spyOn(reducer, 'reduceSession').mockImplementationOnce(() => { throw new Error(`Cannot\napply\u0000update: ${'x'.repeat(600)}`); });
    fake.frame({ v: 1, session: 'session', rev: 1, change: { type: 'run.updated', run: { state: 'idle' } } });
    expect(client.status).toBe('ready');
    expect(client.getAttachment('session')?.state.status).toBe('recovering');
    const recovery = fake.requests.filter(request => request.op === 'attach').at(-1)!;
    fake.reply(recovery, { attachmentId: 'recovered', snapshot: cut('session', 1) });
    await flushMicrotasks();
    expect(client.getAttachment('session')?.state.status).toBe('live');
    expect(client.getAttachment('other')?.state.status).toBe('live');
    expect(diagnostics).toContainEqual({ event: 'attachment.recovering', session: 'session', cause: 'invalid_update', attempts: 0,
      error: `Cannot apply update: ${'x'.repeat(479)}` });
  });

  it('reports another invalid update while recovery is already in flight', async () => {
    const { client, fake, diagnostics } = await fixture();
    fake.onSend = () => {};
    fake.frame(invalidTool(1));
    fake.frame(invalidTool(2));
    expect(diagnostics.filter(event => event.event === 'attachment.recovering')).toEqual([
      { event: 'attachment.recovering', session: 'session', cause: 'invalid_update', attempts: 0, error: expect.any(String) },
      { event: 'attachment.recovering', session: 'session', cause: 'invalid_update', attempts: 1, error: expect.any(String) },
    ]);
    expect(fake.requests.filter(request => request.op === 'attach' && request.session === 'session')).toHaveLength(2);
  });

  it.each(['invalid update', 'resync response'] as const)('does not revive a failed attachment after an %s', async trigger => {
    const { client, fake, diagnostics } = await fixture();
    const original = fake.onSend;
    fake.onSend = () => {};
    const pending = trigger === 'resync response' ? client.request('prompt', { text: 'pending' }, { session: 'session' }) : undefined;
    const command = fake.requests.at(-1)!;
    fake.frame(invalidTool()); await flushMicrotasks();
    const recovery = fake.requests.at(-1)!;
    fake.frame({ v: 1, re: recovery.id, outcome: 'rejected', error: { code: 'busy', message: 'Daemon is draining', retryable: true } });
    await flushMicrotasks();
    const blocked = client.getAttachment('session');
    expect(blocked).toMatchObject({ state: { status: 'blocked', recoveryAttempts: 1 },
      blocked: { kind: 'attach_failed', outcome: 'rejected', code: 'busy', message: 'Daemon is draining' } });
    const sent = fake.requests.length;
    const reported = diagnostics.length;
    fake.onSend = (request, connection) => {
      if (request.op === 'attach') fake.reply(request, { attachmentId: 'retried', snapshot: cut(request.session, 1) }, connection);
      else original(request, connection);
    };
    if (trigger === 'invalid update') fake.frame(invalidTool(2));
    else {
      fake.frame({ v: 1, re: command.id, outcome: 'rejected', error: { code: 'resync_required', message: 'Cutover unavailable', retryable: true } });
      expect(await pending).toMatchObject({ outcome: 'rejected', error: { code: 'resync_required' } });
    }
    await flushMicrotasks();
    expect(client.getAttachment('session')).toEqual(blocked);
    expect(fake.requests).toHaveLength(sent);
    expect(diagnostics).toHaveLength(reported);
    expect(client.getAttachment('other')?.state.status).toBe('live');
    expect(client.status).toBe('ready');
    expect(await client.retryAttach('session')).toMatchObject({ outcome: 'accepted' });
    expect(client.getAttachment('session')?.state).toMatchObject({ status: 'live', recoveryAttempts: 2 });
  });

  it('does not revive an attachment disconnected during update handling', async () => {
    const { client, fake, diagnostics } = await fixture();
    vi.spyOn(reducer, 'reduceSession').mockImplementationOnce(() => {
      fake.lose();
      throw new Error('Disconnected during update');
    });
    const sent = fake.requests.length;
    fake.frame({ v: 1, session: 'session', rev: 1, change: { type: 'run.updated', run: { state: 'idle' } } });
    await flushMicrotasks();
    expect(client.getAttachment('session')?.state).toMatchObject({ status: 'disconnected', recoveryAttempts: 0, bufferGeneration: 0 });
    expect(client.getAttachment('other')?.state.status).toBe('disconnected');
    expect(client.status).toBe('disconnected');
    expect(fake.requests).toHaveLength(sent);
    expect(diagnostics.filter(event => event.event === 'attachment.recovering')).toEqual([]);
  });

  it('blocks only the failing attachment after three recovery attempts', async () => {
    const { client, fake, diagnostics } = await fixture();
    let revision = 0;
    const original = fake.onSend;
    fake.onSend = (request, connection) => {
      if (request.op === 'attach') fake.reply(request, { attachmentId: 'recovered', snapshot: cut(request.session, revision) }, connection);
      else original(request, connection);
    };
    for (revision = 1; revision <= 4; revision++) {
      fake.frame(invalidTool(revision)); await flushMicrotasks();
      fake.frame({ v: 1, session: 'other', rev: revision, change: { type: 'future.optional' } });
    }
    expect(client.getAttachment('session')).toMatchObject({ state: { status: 'blocked', recoveryAttempts: 3 },
      blocked: { kind: 'recovery_limit', cause: 'invalid_update' } });
    expect(client.getAttachment('other')?.state).toMatchObject({ status: 'live', snapshot: { revision: 4 } });
    expect(fake.requests.filter(request => request.op === 'attach' && request.session === 'session')).toHaveLength(4);
    expect(diagnostics).toContainEqual({ event: 'attachment.blocked', session: 'session', attempts: 3,
      reason: { kind: 'recovery_limit', cause: 'invalid_update' }, error: expect.any(String) });
    expect(describeBlocked(client.getAttachment('session')?.blocked)).toBe('resynchronized 3 times in a row; last cause: an invalid session update');
    fake.frame(invalidTool(5)); await flushMicrotasks();
    expect(fake.requests.filter(request => request.op === 'attach' && request.session === 'session')).toHaveLength(4);
    expect(await client.request('prompt', { text: 'still connected' }, { session: 'other' })).toMatchObject({ outcome: 'accepted' });
    expect(client.status).toBe('ready'); expect(fake.closed.size).toBe(0);
  });

  it('renews the recovery budget after the attachment stays live', async () => {
    let now = 1_000_000; vi.spyOn(Date, 'now').mockImplementation(() => now);
    const { client, fake } = await fixture();
    let revision = 0;
    fake.onSend = request => fake.reply(request, { attachmentId: 'recovered', snapshot: cut(request.session!, revision) });
    for (revision = 1; revision <= 3; revision++) { fake.frame(invalidTool(revision)); await flushMicrotasks(); }
    expect(client.getAttachment('session')?.state).toMatchObject({ status: 'live', recoveryAttempts: 3 });
    now += 10_000; fake.frame(invalidTool(revision)); await flushMicrotasks();
    expect(client.getAttachment('session')?.state).toMatchObject({ status: 'live', recoveryAttempts: 1 });
  });

  it.each([invalidTool(2), { ...delta('text'), text: false }])('rejects an in-flight cutover requested before a discarded update', async update => {
    const { client, fake } = await fixture();
    fake.onSend = () => {};
    fake.frame({ v: 1, session: 'session', rev: 2, change: { type: 'future.optional' } });
    const old = fake.requests.at(-1)!;
    fake.frame(update);
    fake.reply(old, { attachmentId: 'old-cut', snapshot: cut('session', 2) });
    await flushMicrotasks();
    expect(client.getAttachment('session')?.state).toMatchObject({ status: 'recovering', recoveryAttempts: 2, bufferGeneration: 1 });
    const current = fake.requests.at(-1)!;
    expect(current.id).not.toBe(old.id);
    fake.reply(current, { attachmentId: 'new-cut', snapshot: cut('session', 2) });
    await flushMicrotasks();
    expect(client.getAttachment('session')?.state.status).toBe('live');
    expect(client.status).toBe('ready');
  });

  it('does not accept a snapshot older than a discarded revision', async () => {
    const { client, fake } = await fixture();
    fake.onSend = () => {};
    fake.frame(invalidTool(2));
    fake.reply(fake.requests.at(-1)!, { attachmentId: 'stale', snapshot: cut('session', 1) });
    await flushMicrotasks();
    expect(client.getAttachment('session')?.state).toMatchObject({ status: 'recovering', discardedRevision: 2 });
    fake.reply(fake.requests.at(-1)!, { attachmentId: 'current', snapshot: cut('session', 2) });
    await flushMicrotasks();
    expect(client.getAttachment('session')?.state.status).toBe('live');
  });

  it.each([
    ['missing session', { ...invalidTool(), session: undefined }],
    ['unattached session', { ...invalidTool(), session: 'unattached' }],
    ['unknown frame', { v: 1, session: 'session', unexpected: true }],
    ['protocol mismatch', { ...invalidTool(), v: 2 }],
    ['response', { ...invalidTool(), re: 'unknown', outcome: 'accepted', result: {} }],
    ['interaction', { ...invalidTool(), interaction: {} }],
    ['presentation', { ...invalidTool(), presentationEvent: {} }],
    ['control', { ...invalidTool(), control: 1 }],
  ])('still blocks the connection for an invalid %s frame', async (_kind, update) => {
    const { client, fake, diagnostics } = await fixture();
    fake.frame(update);
    expect(client.status).toBe('blocked');
    expect(client.getAttachment('session')?.state.status).toBe('disconnected');
    expect(client.getAttachment('other')?.state.status).toBe('disconnected');
    expect(diagnostics.at(-1)).toMatchObject({ event: 'connection.lost', reason: 'invalid_frame' });
  });

  it('still blocks on an invalid correlated response that names an attached session', async () => {
    const { client, fake } = await fixture();
    fake.onSend = () => {};
    const pending = client.request('prompt', { text: 'pending' }, { session: 'session' });
    fake.frame({ ...invalidTool(), re: fake.requests.at(-1)!.id, outcome: 'accepted', result: { sessionId: 'wrong' } });
    expect(await pending).toMatchObject({ outcome: 'indeterminate' });
    expect(client.status).toBe('blocked');
  });

  it('still blocks an update before the reconnect handshake completes', async () => {
    const { client, fake } = await fixture();
    fake.lose();
    fake.onSend = () => fake.frame(invalidTool());
    await expect(client.connect()).rejects.toThrow();
    expect(client.status).toBe('blocked');
  });
});
